export const MITHRIAC_1907_EVIDENCE =
  "G. R. S. Mead, A Mithriac Ritual, Echoes from the Gnosis vol. VI (London and Benares: Theosophical Publishing Society, 1907); public domain (Mead d. 1933). Taken from the archive.org OCR of three independent scans of the 1907 book: the University of Toronto copy (amythicritu06meaduoft, the base text), a Google scan (amithriacritual00meadgoog) and the Servants of Knowledge scan (ult.mithriacritualvo0000grsm). Where the other two scans agreed against the Toronto OCR their reading was taken (42 times); the whole text was then read page by page against the Toronto page images, and the Greek words, the macrons of the vowel block (p. 26) and the obeli (†) were taken from the images. Every correction made by hand is listed in scripts/texts/mead-mithriac-ritual.py. Italic (Mead prints the prayers in italics and the instructions in roman) is not marked; Mead's square brackets are kept; the running head and page numbers are left out.";

const RITUAL_EVIDENCE =
  "Mead's English of the Ritual, made from Dieterich's Greek text (Eine Mithrasliturgie, Leipzig, 1903), as his contents page says ('Text: Dieterich (A.), Eine Mithrasliturgie'). He leaves out the magical names and vowel-strings he took for later insertions; the names he keeps are marked by obeli (†), and only one block of vowels (VII.2) is printed. The section numbers and headings are Mead's; headings in square brackets are his additions.";

function pages(unit: MithriacUnit): string {
  return unit.firstPage === unit.lastPage ? `p. ${unit.firstPage}` : `pp. ${unit.firstPage}–${unit.lastPage}`;
}

function englishLayer(unit: MithriacUnit): CorpusLayer {
  const preamble = unit.id === "preamble";
  return {
    key: "eng-1907",
    layer: preamble ? "interpretation" : "translation",
    sourceKey: "mead-mithriac-ritual-1907",
    content: unit.text,
    language: "English",
    licence: "public_domain",
    evidence: `${MITHRIAC_1907_EVIDENCE} (${preamble ? "the Preamble" : `the Ritual, section ${unit.numeral}`}, ${pages(unit)})${preamble ? " Mead's own introduction, not a translation." : ` ${RITUAL_EVIDENCE}`}`,
  };
}

