function unitPassage(unit: MithriacUnit): CorpusPassage {
  const meta = UNITS[unit.id];
  const key = `${BOOK}.${unit.id}`;
  const preamble = unit.id === "preamble";
  return {
    key,
    parentKey: preamble ? BOOK : RITUAL,
    divisionKind: "section",
    label: meta.label,
    reference: preamble ? `A Mithriac Ritual (London, 1907), Preamble, ${pages(unit)}` : `A Mithriac Ritual (London, 1907), The Ritual, section ${unit.numeral}, ${pages(unit)}`,
    sourceKey: "mead-mithriac-ritual-1907",
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [englishLayer(unit)],
    witnesses: preamble ? undefined : [{ manuscriptKey: "bnf-suppl-gr-574" }],
    themes: meta.themes.map(([themeKey, note]) => ({ themeKey, note })),
    images: imagesFor(MITHRAS_IMAGES, key),
  };
}

function buildPassages(): CorpusPassage[] {
  const preamble = MITHRIAC_UNITS.find((u) => u.id === "preamble")!;
  const sections = MITHRIAC_UNITS.filter((u) => u.id !== "preamble");
  return [
    {
      key: BOOK,
      divisionKind: "book",
      label: "A Mithriac Ritual (London, 1907)",
      reference:
        "G. R. S. Mead, Echoes from the Gnosis, vol. VI: A Mithriac Ritual (London and Benares: The Theosophical Publishing Society, 1907), pp. 9–77: Preamble (p. 9), The Ritual (p. 18), Comments (p. 34)",
      sourceKey: "mead-mithriac-ritual-1907",
      summary:
        "Mead's English of the Greek ritual of ascent that Albrecht Dieterich published in 1903 as 'Eine Mithrasliturgie' from the Great Paris Magical Papyrus (PGM IV 475–829), with his Preamble and Comments: a small volume of his Theosophical series 'Echoes from the Gnosis', following vol. V, The Mysteries of Mithra.",
      notes:
        "Not imported, and listed here: Mead's Comments (pp. 34–77), a running commentary without headings that goes through the Ritual in order, citing its sections ('c. 3'), and compares it with the 'Trismegistic sermons' of his Thrice-Greatest Hermes (cited as T.G.H.), the 'Virgin of the World' (p. 44), the Naassene document, the Oracles, Plato, Proclus and Empedocles; and the front matter (the series note, list of contents and list of the series). The Comments read the rite in Theosophical terms, like the Preamble.",
      verificationStatus: "unverified",
      layers: [DIETERICH],
      dates: [PUBLISHED],
      images: imagesFor(MITHRAS_IMAGES, BOOK),
    },
    unitPassage(preamble),
    {
      key: RITUAL,
      parentKey: BOOK,
      divisionKind: "part",
      label: "The Ritual",
      reference: `A Mithriac Ritual (London, 1907), The Ritual, sections I–XIV, pp. 18–33; PGM IV 475–829 in Preisendanz's numbering`,
      sourceKey: "mead-mithriac-ritual-1907",
      summary:
        "A first-person rite of ascent: after a prayer to hand on immortality from Father to Son, the candidate invokes the elements of his own body, breathes in the sun's rays and rises through the air, silences the gods, passes the doors of fire, meets the young Sun-god, the seven Fortunes and the seven Pole-lords of heaven, and finally a greater god holding the Bear, before whom he is 'born again' and passes beyond birth and death.",
      notes:
        "Preserved in one papyrus, BnF Supplément grec 574, and nowhere else. Mead translates Dieterich's Greek, leaving out most of the magical names and vowels (see the Preamble). The papyrus line numbers PGM IV 475–829 are those of the inventory entry for the whole Ritual; the line numbers of Mead's sections were not established and are not given.",
      verificationStatus: "unverified",
      layers: [],
      witnesses: [{ manuscriptKey: "bnf-suppl-gr-574", locus: "PGM IV 475–829" }],
      dates: [PAPYRUS, COMPOSITION],
      images: imagesFor(MITHRAS_IMAGES, RITUAL),
    },
    ...sections.map(unitPassage),
  ];
}

